  const hashes=recordValue(candidate,'COMPONENT_HASHES');if(!hashes||typeof hashes!=='object'||!Object.keys(hashes).length)reasons.push('The frozen candidate has no application-controlled component hashes.');
  const candidateIds=new Set(runs.map(run=>String(recordValue(run,'CANDIDATE_ID')||run.relationships?.CANDIDATE_ID||'')).filter(Boolean));if(candidateIds.size!==1||candidateId&&![...candidateIds].includes(candidateId))reasons.push('All ten runs must use the exact current candidate identity.');
  const accepted=acceptedChanges(project,Number(iteration?.stage)||([String(purpose).toUpperCase()==='INITIAL'?11:17])).filter(change=>String(change.scope?.iterationId||'')===id),rawIds=new Set(safe(project.projectData.rawResponses).map(item=>item.rawResponseId)),receipts=safe(project.projectData.outputReceipts);
  for(const run of runs){const runId=recordId(run,'runs'),change=accepted.find(item=>String(item.scope?.runId||'')===runId);if(!change||!rawIds.has(change.rawResponseId))reasons.push(`${runId} lacks a current accepted raw response.`);if(!receipts.some(item=>String(item.runId||'')===runId&&String(item.iteration||item.iterationId||'')===id))reasons.push(`${runId} lacks a current output receipt.`);}
  const normalizedPurpose=upper(purpose),requiresVerification=normalizedPurpose!=='INITIAL';let matrix=null;
  if(requiresVerification){matrix=verificationMatrix(project,id);if(!matrix.complete)reasons.push(`The current REQ_ID × RUN_ID × TEST_ID matrix is incomplete or invalid (${matrix.missing.length} missing, ${matrix.duplicates.length} duplicate, ${matrix.invalid.length} invalid).`);if(matrix.violated.length)reasons.push(`${matrix.violated.length} current verification result(s) are VIOLATED.`);if(matrix.undetermined.length)reasons.push(`${matrix.undetermined.length} current verification result(s) are UNDETERMINED.`);}
  if(['CORRECTED','CONFIRMATION'].includes(normalizedPurpose)){
    const requiredOperations=normalizedPurpose==='CONFIRMATION'?['EXECUTE_RUN','VERIFY','COMPARE','REGRESSION_VERIFY','CONFIRM']:['FREEZE','EXECUTE_RUN','VERIFY','COMPARE','ROOT_CAUSE','REGRESSION','CORRECT'],stage=normalizedPurpose==='CONFIRMATION'?19:17,currentOperations=new Set(acceptedChanges(project,stage).filter(change=>String(change.scope?.iterationId||'')===id).map(change=>change.operation||'COMPLETE')),missingOperations=requiredOperations.filter(operation=>!currentOperations.has(operation));if(missingOperations.length)reasons.push(`Required stage operations are missing for ${id}: ${missingOperations.join(', ')}.`);
    const activeRegressions=records(project,'regressions').filter(reg=>upper(recordValue(reg,'ACTIVE_RETIRED_STATE')||'ACTIVE')!=='RETIRED'),executions=currentRegressionExecutions(project,id);for(const regression of activeRegressions){const regId=recordId(regression,'regressions'),matches=executions.filter(item=>String(recordValue(item,'REG_ID')||item.relationships?.REG_ID||'')===regId&&upper(recordValue(item,'PHASE'))!=='PRE_CORRECTION');if(matches.length!==1||!['SATISFIED','SUCCESS','PASSED'].includes(upper(recordValue(matches[0],'RESULT')))||!evaluateEvidenceSufficiency(project,{result:matches[0]}).sufficient)reasons.push(`${regId} lacks one current successful evidence-sufficient regression execution.`);}
  }
  if(normalizedPurpose==='CONFIRMATION'){
    const confirmation=records(project,'confirmationRecords').find(item=>String(recordValue(item,'CONFIRMATION_ITERATION_ID')||item.relationships?.CONFIRMATION_ITERATION_ID||'')===id);if(!confirmation)reasons.push('The unchanged confirmation record is missing.');else if(upper(recordValue(confirmation,'DETERMINATION'))!=='SATISFIED')reasons.push('The unchanged confirmation determination is not SATISFIED.');
  }
